CREATE TABLE IF NOT EXISTS proof_bundles ( id TEXT PRIMARY KEY, subject_id TEXT NOT NULL, claim TEXT NOT NULL, claim_hash TEXT NOT NULL, implementation_hash TEXT, environment_hash TEXT, dependency_hash TEXT, verifier_identity TEXT NOT NULL, verification_status TEXT NOT NULL, evidence_json TEXT NOT NULL DEFAULT '[]', formal_proofs_json TEXT NOT NULL DEFAULT '[]', independent_oracles_json TEXT NOT NULL DEFAULT '[]', replay_results_json TEXT NOT NULL DEFAULT '[]', source_references_json TEXT NOT NULL DEFAULT '[]', limitations_json TEXT NOT NULL DEFAULT '[]', reproducibility_instructions TEXT, created_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS proof_evidence ( id TEXT PRIMARY KEY, proof_bundle_id TEXT NOT NULL REFERENCES proof_bundles(id), evidence_type TEXT NOT NULL, content_json TEXT NOT NULL, receipt_hash TEXT NOT NULL, created_at BIGINT NOT NULL );
CREATE TABLE IF NOT EXISTS tests ( id TEXT PRIMARY KEY, proof_bundle_id TEXT REFERENCES proof_bundles(id), name TEXT NOT NULL, description TEXT NOT NULL, passed BOOLEAN NOT NULL DEFAULT FALSE, duration_ms DOUBLE PRECISION NOT NULL DEFAULT 0, receipt_hash TEXT, created_at BIGINT NOT NULL );
